INSERT INTO	ENT_ANALYSIS_JOB
(
	REFERENCE_ID
	, DIVISION
	, ANALYSIS_START_DATE
	, TOTAL_COUNT
)
VALUES
(
	#{referenceId}
	, #{division}
	, now()
	, #{totalCount}
)

mapper.select:
SELECT JOB_SEQ
FROM OSS_ANALYSIS_STATUS
WHERE PRJ_ID = #{prjId}

mapper.update:
UPDATE ENT_ANALYSIS_JOB T1
INNER JOIN ENT_ANALYSIS_JOB_DETAILS T2
SET T1.SUCCESS_COUNT = SUCCESS_COUNT + 1, T1.FAILURE_COUNT = GREATEST(FAILURE_COUNT - 1, 0), T2.REFERENCE_OSS_ID = #{ossId}
WHERE T1.JOB_SEQ = #{jobSeq}
AND (T1.SUCCESS_COUNT + 1) <= T1.TOTAL_COUNT
AND T2.OSS_NAME = #{ossName}
AND IFNULL(T2.OSS_VERSION, '') = IFNULL(#{ossVersion}, '')
